// Flatten the raw Gmail payload into clean fields used by every later node
const e = $json;
const fromObj = (e.from && e.from.value && e.from.value[0]) || {};
const address = (fromObj.address || '').toLowerCase();
const body = (e.text || e.snippet || '').toString();

return {
  json: {
    message_id: e.id,
    thread_id: e.threadId,
    from_email: address,
    from_name: fromObj.name || '',
    sender_domain: address.split('@')[1] || '',
    subject: e.subject || '(no subject)',
    body: body.replace(/\n{3,}/g, '\n\n').slice(0, 6000),
    received_at: e.date || new Date().toISOString()
  }
};

