const raw = $json.message?.content ?? $json.content ?? $json.text ?? '';
let parsed = raw;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  try { parsed = JSON.parse(cleaned); } catch (err) { parsed = { __parse_error: cleaned.slice(0, 300) }; }
}

const c = parsed || {};
const email = $('Normalize Email').item.json;
const freeMail = ['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','proton.me','protonmail.com','live.com','aol.com'];
const corporateDomain = email.sender_domain && !freeMail.includes(email.sender_domain);
const deliverables = Array.isArray(c.deliverables) && c.deliverables.length
  ? c.deliverables.map(d => ({ platform: d.platform || 'youtube', format: d.format || 'integration', quantity: Number(d.quantity) || 1 }))
  : [];
const scam = Array.isArray(c.scam_signals) ? c.scam_signals : [];
if (!corporateDomain && c.brand_name) scam.push('Sender uses a free email domain');

return {
  json: {
    ...email,
    is_sponsorship: c.is_sponsorship === true,
    deal_type: c.deal_type || 'not_a_deal',
    confidence: Number(c.confidence) || 0,
    brand_name: c.brand_name || email.from_name || email.sender_domain,
    brand_website: c.brand_website || (corporateDomain ? 'https://' + email.sender_domain : ''),
    contact_name: c.contact_name || (email.from_name || '').split(' ')[0] || '',
    offered_amount: (c.offered_amount === null || c.offered_amount === undefined || c.offered_amount === '') ? null : Number(c.offered_amount),
    offer_currency: c.currency || 'USD',
    deliverables,
    deliverables_text: deliverables.length ? deliverables.map(d => `${d.quantity}x ${d.platform} ${d.format}`).join(', ') : 'not specified',
    usage_rights_requested: c.usage_rights_requested === true,
    usage_rights_days: Number(c.usage_rights_days) || null,
    exclusivity_requested: c.exclusivity_requested === true,
    deadline: c.deadline || '',
    scam_signals: scam,
    summary: c.summary || '',
    classification_error: c.__parse_error || ''
  }
};

// Turn both Tavily responses into compact text blocks for the AI
const safe = (name) => { try { return $(name).item.json || {}; } catch (e) { return {}; } };
const fmt = (r) => {
  if (r.error) return 'Search failed: ' + (r.error.message || JSON.stringify(r.error)).slice(0, 200);
  const res = Array.isArray(r.results) ? r.results : [];
  const answer = r.answer ? 'Summary: ' + r.answer + '\n\n' : '';
  const list = res.slice(0, 5).map((x, i) => `[${i + 1}] ${x.title} (${x.url})\n${(x.content || '').slice(0, 500)}`).join('\n\n');
  return (answer + list).trim() || 'No results found';
};

const deal = $('Parse Classification').item.json;
return {
  json: {
    ...deal,
    research_funding: fmt(safe('Research: Funding')),
    research_campaigns: fmt(safe('Research: Past Campaigns'))
  }
};

