const raw = $json.message?.content ?? $json.content ?? $json.text ?? '';
let parsed = raw;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  try { parsed = JSON.parse(cleaned); } catch (err) { parsed = { __parse_error: cleaned.slice(0, 300) }; }
}

const p = parsed || {};
const deal = $('Compile Research').item.json;
return {
  json: {
    ...deal,
    funding_stage: p.funding_stage || 'unknown',
    total_funding_usd: p.total_funding_usd ?? null,
    last_round: p.last_round || '',
    brand_tier: p.brand_tier || 'unknown',
    past_creator_campaigns: Array.isArray(p.past_creator_campaigns) ? p.past_creator_campaigns : [],
    creator_budget_signal: p.creator_budget_signal || 'unknown',
    legitimacy_score: Number.isFinite(Number(p.legitimacy_score)) ? Number(p.legitimacy_score) : 50,
    red_flags: Array.isArray(p.red_flags) ? p.red_flags : [],
    brand_summary: p.one_line_summary || ''
  }
};

// Deterministic pricing engine: audience size x CPM x format x brand/usage multipliers
const d = $json;
const round50 = (n) => Math.max(50, Math.round(n / 50) * 50);

// Average impressions per platform
const reach = {
  youtube: d.youtube_avg_views,
  instagram: d.instagram_avg_reel_views,
  tiktok: d.instagram_avg_reel_views,
  linkedin: Math.round(d.linkedin_followers * 0.15),
  x: Math.round(d.linkedin_followers * 0.1),
  newsletter: Math.round(d.newsletter_subscribers * 0.45),
  podcast: Math.round(d.youtube_avg_views * 0.4),
  other: d.youtube_avg_views
};
// Relative value of each format vs a dedicated video
const formatMult = { dedicated_video: 1.0, integration: 0.6, livestream: 0.8, newsletter: 0.5, reel: 0.45, short: 0.35, post: 0.3, story: 0.15, other: 0.5 };

const deliverables = d.deliverables.length ? d.deliverables : [{ platform: 'youtube', format: 'integration', quantity: 1 }];
const breakdown = [];
let base = 0;
for (const del of deliverables) {
  const views = reach[del.platform] ?? reach.other;
  const line = (views / 1000) * d.base_cpm * (formatMult[del.format] ?? 0.5) * del.quantity;
  base += line;
  breakdown.push(`${del.quantity}x ${del.platform} ${del.format}: ~${views.toLocaleString()} views -> ${Math.round(line)}`);
}

// Multipliers
const er = d.engagement_rate_pct;
const erMult = er >= 6 ? 1.25 : er >= 3 ? 1.1 : er >= 1.5 ? 1.0 : 0.9;
const tierMult = { enterprise: 1.4, established: 1.25, growth: 1.1, startup: 0.9, unknown: 1.0 }[d.brand_tier] ?? 1.0;
const fundingBoost = ['series_b_plus', 'public', 'enterprise'].includes(d.funding_stage) ? 0.1 : 0;
const usageMult = d.usage_rights_requested ? 1 + Math.min(1, Math.max(0.2, ((d.usage_rights_days || 30) / 30) * 0.1)) : 1;
const exclMult = d.exclusivity_requested ? 1.2 : 1;
let rushMult = 1;
if (d.deadline) {
  const days = (new Date(d.deadline) - new Date()) / 86400000;
  if (!isNaN(days) && days < 7) rushMult = 1.15;
}

const total = base * erMult * (tierMult + fundingBoost) * usageMult * exclMult * rushMult;
const suggested = round50(Math.max(total, d.min_deal_rate));
const counterAsk = round50(suggested * 1.15);
const walkAway = round50(Math.max(d.min_deal_rate, suggested * 0.8));

// Negotiation strategy
const offered = d.offered_amount;
const riskyBrand = d.legitimacy_score < 40 || d.scam_signals.length >= 2;
let strategy, counter, upsell = '';
if (riskyBrand) { strategy = 'verify_first'; counter = suggested; }
else if (d.deal_type === 'affiliate' || d.deal_type === 'gifted_product') { strategy = 'convert_to_paid'; counter = suggested; }
else if (offered === null || isNaN(offered)) { strategy = 'quote_rate'; counter = counterAsk; }
else if (offered >= suggested) { strategy = 'accept_with_upsell'; counter = offered; upsell = 'Add a short-form cut-down (Short/Reel) for an extra ' + round50(suggested * 0.25) + ' ' + d.currency; }
else if (offered >= walkAway) { strategy = 'counter_meet_near'; counter = suggested; }
else { strategy = 'counter_anchor'; counter = counterAsk; upsell = 'Offer a lighter package (fewer deliverables) if budget is fixed'; }

return {
  json: {
    ...d,
    suggested_rate: suggested,
    counter_ask: counterAsk,
    walk_away_floor: walkAway,
    counter_amount: counter,
    strategy,
    upsell_idea: upsell,
    currency_mismatch: d.offer_currency && d.offer_currency !== d.currency,
    rate_breakdown: breakdown.join(' | ') + ` | multipliers: engagement ${erMult}, brand ${(tierMult + fundingBoost).toFixed(2)}, usage ${usageMult.toFixed(2)}, exclusivity ${exclMult}, rush ${rushMult}`,
    audience_proof: `${d.youtube_subscribers.toLocaleString()} YouTube subs (~${d.youtube_avg_views.toLocaleString()} avg views), ${d.instagram_followers.toLocaleString()} Instagram followers, ${er}% engagement. Media kit: ${d.media_kit_url}`
  }
};

